def seed(database: Database) -> tuple[int, int]:
    """رفع الأمراض ثم استبدال أسئلتها، بحيث يمكن تشغيل السكربت أكثر من مرة."""
    disease_count = 0
    question_count = 0
    for item in DISEASES:
        questions = item["questions"]
        disease_payload = {key: value for key, value in item.items() if key != "questions"}
        response = database.client.table("diseases").upsert(disease_payload, on_conflict="name_en").execute()
        if response.data:
            disease_id = response.data[0]["id"]
        else:
            found = database.client.table("diseases").select("id").eq("name_en", item["name_en"]).limit(1).execute()
            if not found.data:
                raise RuntimeError(f"تعذر العثور على المرض بعد إضافته: {item['name_ar']}")
            disease_id = found.data[0]["id"]
        disease_count += 1

        database.client.table("questions").delete().eq("disease_id", disease_id).execute()
        payload = [{**question, "disease_id": disease_id} for question in questions]
        database.client.table("questions").insert(payload).execute()
        question_count += len(payload)
    return disease_count, question_count


def main() -> None:
    """تشغيل الإدخال برسائل عربية واضحة ومن دون طباعة أسرار."""
    try:
        settings = Settings.from_env()
        database = Database(settings.supabase_url, settings.supabase_key)
        diseases, questions = seed(database)
        print(f"تمت إضافة أو تحديث {diseases} أمراض و{questions} سؤالًا بنجاح.")
    except Exception as exc:
        print(f"تعذر إدخال البيانات: {exc.__class__.__name__}", file=sys.stderr)
        raise SystemExit(1) from exc


if __name__ == "__main__":
    main()
